export function toGravityChartsData(data: SalesData): GravityChartsWidgetData {
  return {
    data: {
      colors: [...SERIES_COLORS],
      legend: {enabled: true},
      series: {
        data: data.series.map((series, index) => ({
          type: 'line' as const,
          name: series.name,
          color: seriesColor(index),
          lineWidth: 2,
          data: series.points.map((point) => ({x: point.date, y: point.value})),
        })),
      },
      xAxis: {
        type: 'datetime',
      },
      yAxis: [
        {
          title: data.valueAxisTitle ? {text: data.valueAxisTitle} : undefined,
        },
      ],
    },
  };
}

